package apr11__18_collection;

public class A15_B_while_loop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int a =0;
		
		while( a <= 20) {
			
			System.out.println(a);
			a++;
		}
		
        int b =0;
		
		while( b <= 20) {
			
			System.out.println(b);
			a--;
		}

	}

}
